//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			HE_DrumFilterControl                                                                                                                                                                                                                                                                          
//	CREATOR:		Helgevold - William Veim                                                                                                                                                                                                                                                              
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION		DATE				SIGN						DESCRIPTION                                                                                                                                                                                     
//	1.0.0				2026-05-19		William Veim			Initial release
//
//===============================================================================================================================
//
//		DESCRIPTION:
//		Control of muliple drum filter whit flushing and rotation (in case of nozzle movement, use same output as flushing)
//			*Maximum 10 filter
//			
//			*Normal flushing sequence 
//				-Start based on level (or diff level)
//	
//================================================================================================================================

(*************************************************************************
 *	INITIAL/SYSTEM VARIABELS
 *************************************************************************)
 
DtToDateStruct(In:=GetTime(), DateStruct=>DateStruct);

 (*************************************************************************
 *	INITIALIZE VARIABELS
 *************************************************************************)
 
Ext_DrumFilterControl.EXT_General.LocationIndex[0]:=Cfg_MainLocation; //First index / main location is forced; remaining tree optional can be set in SCADA
Ext_DrumFilterControl.EXT_General.NumberOfFilter_Used:= Cfg_NumOfFilter;

IF NOT Ext_DrumFilterControl.INT_Data.Initialise THEN
	
	//Operator parameteres
	Ext_DrumFilterControl.EXT_Operator.FlushSeq_NumOfFilter:=1;
	Ext_DrumFilterControl.EXT_Operator.FlushSeq_StartDelay:=5;
	Ext_DrumFilterControl.EXT_Operator.FlushSeq_StartLevel:=10;
	Ext_DrumFilterControl.EXT_Operator.RotationSeq_StartDelay:=20;
	
	//Engeneering parameters
	Ext_DrumFilterControl.EXT_Engineering.FlushSeq_DelayFlushing:=1;
	Ext_DrumFilterControl.EXT_Engineering.FlushSeq_DelayRotation:=0;
	Ext_DrumFilterControl.EXT_Engineering.FlushSeq_Duration:= 20;
	Ext_DrumFilterControl.EXT_Engineering.FlushSeq_ForcedStartTime:=10;
	Ext_DrumFilterControl.EXT_Engineering.FlushSeq_Output:=10;
	Ext_DrumFilterControl.EXT_Engineering.RotationSeq_Active:=FALSE;
	Ext_DrumFilterControl.EXT_Engineering.RotationSeq_Duration:=15;
	Ext_DrumFilterControl.EXT_Engineering.RotationSeq_Output:=5;
	
	//State config 
	Ext_DrumFilterControl.EXT_Engineering.StateCfg_1.Cfg_Quality:=1; //Output module fault = Equipment failiure
	Ext_DrumFilterControl.EXT_Engineering.StateCfg_1.Cfg_Alarm:=TRUE; //Output module fault = Alarm
	Ext_DrumFilterControl.EXT_Engineering.StateCfg_2.Cfg_Quality:=1; //Feedback module fault = Equipment failiure
	Ext_DrumFilterControl.EXT_Engineering.StateCfg_2.Cfg_Alarm:=TRUE; //Feedback module fault = Alarm
	
	//Alarm settings
	Ext_DrumFilterControl.EXT_Alarm.Cfg_SupressDelayOff:=10;
	Ext_DrumFilterControl.EXT_Alarm.Cfg_AlarmActiveDelay:=10;
	Ext_DrumFilterControl.EXT_Alarm.Cfg_AlarmReturnDelay:=10;
	
	//Init complete
	Ext_DrumFilterControl.INT_Data.Initialise:=TRUE;
	
END_IF;

(*************************************************************************
 *	UPDATING PID INPUT VALUES
 *************************************************************************)
 
HE_PV_Select(EXT_AnalogValue:=Ext_AnalogValue, 
					 PV_Select:=Ext_DrumFilterControl.EXT_Operator.PV_Select, 
					 PV_AutoSwitch:=Ext_DrumFilterControl.EXT_Engineering.PV_AutoSwitch, 
					 PV_AutoSwitchState:=Ext_DrumFilterControl.EXT_Engineering.PV_AutoSwitchState, 
					 PV_Actual=>Ext_DrumFilterControl.EXT_Operator.PV_Actual,
					 PV_NotAvailable=>Wrk_PVNotAvailable, 
					 PV_MultipleUsed=>Ext_DrumFilterControl.EXT_General.PV_ValueChange_Visible, 
					 PV_Value1_Index:=Ext_DrumFilterControl.EXT_Engineering.Cfg_PV_Value1, 
					 PV_Value2_Index:=Ext_DrumFilterControl.EXT_Engineering.Cfg_PV_Value2, 
					 PV_Value3_Index:=Ext_DrumFilterControl.EXT_Engineering.Cfg_PV_Value3);

 (*************************************************************************
 *	TIME ACCUMULATION
 *************************************************************************)

Wrk_HighestStandby_Comp:=TIME#0s;
Wrk_NumberFilterAvailable:=0;

FOR Wrk_IndexFilterLookup:=0 TO 9 DO
	
	IF Int_ActuatorData_Motor[Wrk_IndexFilterLookup].AvailableAuto AND Int_ActuatorData_Valve[Wrk_IndexFilterLookup].AvailableAuto THEN
		
		Wrk_NumberFilterAvailable:=	Wrk_NumberFilterAvailable + 1;
	END_IF;
	
	IF NOT Int_ActuatorData_Motor[Wrk_IndexFilterLookup].AutoStart AND NOT Int_ActuatorData_Valve[Wrk_IndexFilterLookup].AutoStart THEN
		
		Wrk_TimeSinceLastFlush[Wrk_IndexFilterLookup]:= 	ADD_TIME(In1:=Wrk_TimeSinceLastFlush[Wrk_IndexFilterLookup], In2:=GetMyTaskInterval());
	END_IF;

	IF NOT Wrk_FlushingSeq
		AND Int_ActuatorData_Motor[Wrk_IndexFilterLookup].AvailableAuto
		AND Int_ActuatorData_Valve[Wrk_IndexFilterLookup].AvailableAuto THEN
	
		IF Wrk_TimeSinceLastFlush[Wrk_IndexFilterLookup] > Wrk_HighestStandby_Comp THEN
		
		Wrk_FilterIndex_FlushSeq:=				Wrk_IndexFilterLookup;	
		Wrk_HighestStandby_Comp:=			Wrk_TimeSinceLastFlush[Wrk_IndexFilterLookup];
		
		ELSE
		
		Wrk_FilterIndex_FlushSeq_Sec:= 		Wrk_IndexFilterLookup;
		END_IF;
	END_IF;
END_FOR;

(*************************************************************************
 *	VARIABLE CONTROL
 *************************************************************************)

//FLUSHING SEQUENCE
//Two start cirteria: Level above threshold longer than delay time, OR minutes since last flushing above threshold
//--------------------------------------------------------------------------------------------------------------------------

//Start by high level
TON_FlushSeq_Start(In:=(Ext_DrumFilterControl.EXT_Operator.PV_Actual.ProcessValue>Ext_DrumFilterControl.EXT_Operator.FlushSeq_StartLevel) AND NOT Wrk_FlushingSeq, PT:=SecToTime(Ext_DrumFilterControl.EXT_Operator.FlushSeq_StartDelay));

//Start by time
Wrk_ForcedStart:=Wrk_TimeSinceLastFlush[Wrk_FilterIndex_FlushSeq] > SecToTime(Ext_DrumFilterControl.EXT_Engineering.FlushSeq_ForcedStartTime * 60) AND NOT Wrk_FlushingSeq;

TON_FlushSeq_FlushDelay(In:=		Wrk_FlushingSeq, PT:=	SecToTime(Ext_DrumFilterControl.EXT_Engineering.FlushSeq_DelayFlushing));
TON_FlushSeq_RotationDelay(In:=	Wrk_FlushingSeq, PT:=	SecToTime(Ext_DrumFilterControl.EXT_Engineering.FlushSeq_DelayRotation));
TON_FlushSeq_Duration(In:=			Wrk_FlushingSeq, PT:=	SecToTime(Ext_DrumFilterControl.EXT_Engineering.FlushSeq_Duration));

//Activate sequece based on start conditions
IF TON_FlushSeq_Start.Q OR Wrk_ForcedStart THEN
	Wrk_FlushingSeq:=	TRUE;
END_IF;

//Flushing sequence
IF Wrk_FlushingSeq THEN
	
	//Start rotation
	IF TON_FlushSeq_RotationDelay.Q THEN
		Int_ActuatorData_Motor[Wrk_FilterIndex_FlushSeq].AutoStart:=TRUE;
		Int_ActuatorData_Motor[Wrk_FilterIndex_FlushSeq].AutoReference:=Ext_DrumFilterControl.EXT_Engineering.FlushSeq_Output;
		
		IF Ext_DrumFilterControl.EXT_Operator.FlushSeq_NumOfFilter = 2 THEN
			Int_ActuatorData_Motor[Wrk_FilterIndex_FlushSeq_Sec].AutoStart:=TRUE;
			Int_ActuatorData_Motor[Wrk_FilterIndex_FlushSeq_Sec].AutoReference:=Ext_DrumFilterControl.EXT_Engineering.FlushSeq_Output;
		END_IF;
	END_IF;
	
	//Open flush valve
	IF TON_FlushSeq_FlushDelay.Q THEN
		Int_ActuatorData_Valve[Wrk_FilterIndex_FlushSeq].AutoStart:=TRUE;
		Int_ActuatorData_Valve[Wrk_FilterIndex_FlushSeq].AutoReference:=0; //N/A
		
		IF Ext_DrumFilterControl.EXT_Operator.FlushSeq_NumOfFilter = 2 THEN
			Int_ActuatorData_Valve[Wrk_FilterIndex_FlushSeq_Sec].AutoStart:=TRUE;
			Int_ActuatorData_Valve[Wrk_FilterIndex_FlushSeq_Sec].AutoReference:=0; //N/A
		END_IF;
	END_IF;
	
	IF TON_FlushSeq_Duration.Q THEN
		
		//Stop motor
		Int_ActuatorData_Motor[Wrk_FilterIndex_FlushSeq].AutoStart:=FALSE;
		Int_ActuatorData_Motor[Wrk_FilterIndex_FlushSeq].AutoReference:=0;
		
		//Close valve
		Int_ActuatorData_Valve[Wrk_FilterIndex_FlushSeq].AutoStart:=FALSE;
		Int_ActuatorData_Valve[Wrk_FilterIndex_FlushSeq].AutoReference:=0; //N/A
		
		IF Ext_DrumFilterControl.EXT_Operator.FlushSeq_NumOfFilter = 2 THEN
			Int_ActuatorData_Motor[Wrk_FilterIndex_FlushSeq_Sec].AutoStart:=FALSE;
			Int_ActuatorData_Motor[Wrk_FilterIndex_FlushSeq_Sec].AutoReference:=0;
			Int_ActuatorData_Valve[Wrk_FilterIndex_FlushSeq_Sec].AutoStart:=FALSE;
			Int_ActuatorData_Valve[Wrk_FilterIndex_FlushSeq_Sec].AutoReference:=0; //N/A
		END_IF;
		
		//Stop sequence
		Wrk_FlushingSeq:=FALSE;
		Wrk_TimeSinceLastFlush[Wrk_FilterIndex_FlushSeq]:= TIME#0s;
		IF Ext_DrumFilterControl.EXT_Operator.FlushSeq_NumOfFilter = 2 THEN
			Wrk_TimeSinceLastFlush[Wrk_FilterIndex_FlushSeq_Sec]:= TIME#0s;
		END_IF;
		
		IF Ext_DrumFilterControl.EXT_Engineering.RotationSeq_Active THEN
			Wrk_StartRotationSeq[Wrk_FilterIndex_FlushSeq]:=TRUE;
		END_IF;
		
	END_IF;
	
END_IF;

//ROTATION SEQUENCE
//Started after normal flushing sequence - After delay
//--------------------------------------------------------------------------------------------------------------------------

FOR Wrk_IndexFilterLookup:=0 TO 9 DO
	IF Wrk_StartRotationSeq[Wrk_IndexFilterLookup] AND NOT Wrk_RotationSeq THEN
		Wrk_FilterIndex_RotSeq:=Wrk_IndexFilterLookup;
		Wrk_RotationSeq:=TRUE;
	END_IF;
END_FOR;

TON_RotationSeq_Delay(In:=		Wrk_RotationSeq, PT:=SecToTime(Ext_DrumFilterControl.EXT_Operator.RotationSeq_StartDelay));
TON_RotationSeq_Duration(In:=	Wrk_RotationSeq AND TON_RotationSeq_Delay.Q, PT:=SecToTime(Ext_DrumFilterControl.EXT_Engineering.RotationSeq_Duration));

IF TON_RotationSeq_Delay.Q THEN
	
	Int_ActuatorData_Motor[Wrk_FilterIndex_RotSeq].AutoStart:=TRUE;
	Int_ActuatorData_Motor[Wrk_FilterIndex_RotSeq].AutoReference:=Ext_DrumFilterControl.EXT_Engineering.RotationSeq_Output;
		
	IF TON_RotationSeq_Duration.Q THEN	

	Int_ActuatorData_Motor[Wrk_FilterIndex_RotSeq].AutoStart:=FALSE;
	Int_ActuatorData_Motor[Wrk_FilterIndex_RotSeq].AutoReference:=0;
	
	Wrk_StartRotationSeq[Wrk_FilterIndex_RotSeq]:=FALSE;
	Wrk_RotationSeq:=FALSE;
	
	END_IF;
END_IF;

(*************************************************************************
 *	STATISTICS
 *************************************************************************)

 FOR Wrk_Index:=0 TO 9 DO
	 Ext_DrumFilterControl.EXT_Statistics.TimeSinceLastFlushing[Wrk_Index]:=LINT_TO_UINT(TimeToSec(Wrk_TimeSinceLastFlush[Wrk_Index])) / 60;
 END_FOR;
 
 RE_FlushSeq(Clk:=Wrk_FlushingSeq);
	
IF RE_FlushSeq.Q THEN
	Ext_DrumFilterControl.EXT_Statistics.TotalFlushing_Today:=	Ext_DrumFilterControl.EXT_Statistics.TotalFlushing_Today+1;
	Ext_DrumFilterControl.EXT_Statistics.TotalFlushing_Week:=	Ext_DrumFilterControl.EXT_Statistics.TotalFlushing_Week+1;
	Ext_DrumFilterControl.EXT_Statistics.TotalFlushing_Month:=	Ext_DrumFilterControl.EXT_Statistics.TotalFlushing_Month+1;
	Ext_DrumFilterControl.EXT_Statistics.TotalFlushing_Year:=		Ext_DrumFilterControl.EXT_Statistics.TotalFlushing_Year+1;
	Ext_DrumFilterControl.EXT_Statistics.TotalFlushing:=				Ext_DrumFilterControl.EXT_Statistics.TotalFlushing+1;
END_IF;
	
//Checks if new day
IF DateStruct_Sample.Day <> DateStruct.Day THEN
	Ext_DrumFilterControl.EXT_Statistics.TotalFlushing_Yesterday:= Ext_DrumFilterControl.EXT_Statistics.TotalFlushing_Today;
	Clear(Ext_DrumFilterControl.EXT_Statistics.TotalFlushing_Today);
END_IF;

//Checks if new week
IF GetWeekOfYear(DateStructToDt(DateStruct_Sample)) <> GetWeekOfYear(DateStructToDt(DateStruct)) THEN
	Clear(Ext_DrumFilterControl.EXT_Statistics.TotalFlushing_Week);
END_IF;

//Checks if new month
IF DateStruct_Sample.Month <> DateStruct.Month THEN
	Clear(Ext_DrumFilterControl.EXT_Statistics.TotalFlushing_Month);
END_IF;
			
//Checks if new year
IF DateStruct_Sample.Year <> DateStruct.Year THEN
	Clear(Ext_DrumFilterControl.EXT_Statistics.TotalFlushing_Year);
END_IF;

// Sampling date
DtToDateStruct(In:=GetTime(), DateStruct=>DateStruct_Sample);	
	
(*************************************************************************
 *	STATUS STRING
 *************************************************************************)	

IF Wrk_FlushingSeq THEN
	Ext_DrumFilterControl.EXT_Operator.FlushSeq_Status:= 'Flushing ongoing';
ELSE
	Ext_DrumFilterControl.EXT_Operator.FlushSeq_Status:= 'Standby';
END_IF;
	
IF Wrk_RotationSeq THEN
	Ext_DrumFilterControl.EXT_Operator.RotationSeq_Status:= 'Rotation ongoing';
ELSE
	Ext_DrumFilterControl.EXT_Operator.RotationSeq_Status:= 'Standby';
END_IF;	
	
(*************************************************************************
 *	STATE CONTROL
 *************************************************************************)
 
// STATE CONTROL
//------------------

//Resetter variabler før løkke
Ext_DrumFilterControl.EXT_General.Sts_Quality :=  6; //Good
Wrk_ActionState:=	0;

//STATE 1 - No filter available
HE_StateControl(EXT_StateData:=Ext_DrumFilterControl.EXT_Engineering.StateCfg_1, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_NumberFilterAvailable = 0, 
							Inp_Desc:='No filter available', 
							Sts_Quality:=Ext_DrumFilterControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[0].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[0].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[0].Alm_Priority);

//STATE 2 - One or more filter have been standy over 600min
HE_StateControl(EXT_StateData:=Ext_DrumFilterControl.EXT_Engineering.StateCfg_2, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_TimeSinceLastFlush[Wrk_FilterIndex_FlushSeq] > TIME#600m, 
							Inp_Desc:='Too high standby time', 
							Sts_Quality:=Ext_DrumFilterControl.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[1].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[1].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[1].Alm_Priority);

(*************************************************************************
 *	ALARM CONTROL
 *************************************************************************)

//Supress if off mode
IF Ext_DrumFilterControl.EXT_Alarm.Sts_SupressIfOff_Visible AND Ext_DrumFilterControl.EXT_Alarm.Cfg_SupressIfOff AND Ext_DrumFilterControl.EXT_Operator.Mode = 0 THEN
	FB_AlarmLogic.Inp_AlarmSupress:=TRUE;
	FB_AlarmLogic.Inp_AlmSuppressDesc:= 'Off mode';
//Supress from FB input
ELSIF Inp_AlmSuppress THEN
	FB_AlarmLogic.Inp_AlarmSupress:=TRUE;
	FB_AlarmLogic.Inp_AlmSuppressDesc:= Inp_AlmSuppressDesc;
ELSE
	FB_AlarmLogic.Inp_AlarmSupress:=FALSE;
	FB_AlarmLogic.Inp_AlmSuppressDesc:= '';
END_IF;

(*************************************************************************
 *	EXCECUTING ALARM BLOCK
 *************************************************************************)
 
 FB_AlarmLogic(ENS:=TRUE, 
								 Ext_Alarm:=Ext_DrumFilterControl.EXT_Alarm, 
								 Int_Alarm:=Int_Alarm, 
								 Inp_AlarmData:=Wrk_AlarmData,
								 Inp_LocationData:=Ext_DrumFilterControl.EXT_General.LocationIndex,
								 Inp_Connected_Cabinet:='', 
								 Inp_Connected_Controller:=Cfg_ControllerName, 
								 Inp_Process_TAG:='',
								 Inp_Process_Value:= '',
								 Inp_Process_Desc:=Ext_DrumFilterControl.EXT_General.Process_Desc,
								 Out_AlarmToken=>Wrk_AlarmToken, 
								 Out_AlarmTriggered=>Wrk_AlarmTriggered);

(*************************************************************************
 *	UPDATE OUTPUT
 *************************************************************************)
 

 Sts_Alarm:=Wrk_AlarmTriggered;
